// Caret Worker - SINGLE FILE BUILD. Do not edit this one.
//
// Generated by tools/bundle-worker.py from worker/src/index.js and
// src/shared/proofread.js. Edit those and run the script again.
//
// This exists so the Worker can be deployed by pasting it into the Cloudflare
// dashboard's editor, with no Node and no wrangler. After pasting, the Worker
// still needs its two bindings adding under Settings:
//
//   Workers AI  ->  variable name  AI
//   KV namespace ->  variable name  KEYS
//
// and, optionally, two plain text variables:
//
//   MODEL           @cf/meta/llama-3.1-8b-instruct
//   PER_KEY_DAILY   120

// The proofreading contract: the instructions the model is given and the shape
// it must answer in.
//
// This lives on its own because two very different things need exactly the same
// copy of it: the extension, when it calls a provider directly with the user's
// own key, and the Caret Worker, which calls Cloudflare Workers AI on the
// server. If the two ever drift, the same text gets checked differently
// depending on which one answered, which is the kind of bug nobody reports
// because it just feels inconsistent.
//
// The Worker imports this file at build time, so there is one copy, not two.

const SYSTEM_PROMPT = [
  'You are a meticulous copy editor working inside a browser extension.',
  'You are given the raw contents of a text field the user is writing in.',
  'Report only real mistakes and clear improvements a careful editor would',
  'mark: spelling, grammar, verb tense, agreement, pronouns, punctuation,',
  'and sentences that are genuinely confusing.',
  '',
  'Rules:',
  '- NEVER rewrite a sentence, a clause, or a paragraph. The only thing you',
  '  may propose is swapping a word, or at most a short phrase of a few',
  '  words, for a better one. If a sentence can only be improved by rewriting',
  '  it, say nothing about it.',
  '- Never rewrite for taste. Leave voice, tone, dialect and formatting alone.',
  '- Ignore missing capitals or full stops in short fragments; people write',
  '  notes, search terms and chat messages in this box too.',
  '- Never comment on names, addresses, URLs, code, or anything in brackets',
  '  that looks like a template or placeholder.',
  '- "original" must be copied character for character from the text, and be',
  '  as short as possible while still being fixable on its own.',
  '- "before" must be the 10 characters that immediately precede "original"',
  '  in the text (fewer only at the very start). Copy them exactly.',
  '- "replacement" must be the corrected version of "original" alone.',
  '- Explanations are one short sentence, in plain language.',
  '- If the text is already correct, return an empty list.',
  '',
  'Vocabulary:',
  '- Use plain, everyday words. Do NOT replace an ordinary word with a fancier',
  '  or more formal one. "use" does not become "utilize", "help" does not',
  '  become "facilitate", "about" does not become "regarding".',
  '- Never make the writing sound more advanced, more academic or more',
  '  professional than it already is. That is not a mistake to fix.',
  '- Only propose a different word when the one written is actually WRONG:',
  '  misspelled, the wrong word entirely (their/there), or the wrong form',
  '  (verb tense, singular/plural). Never for sounding better.',
  '- A replacement should be as simple as, or simpler than, what it replaces.',
].join('\n');

const SCHEMA = {
  type: 'object',
  properties: {
    corrections: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          before: { type: 'string' },
          original: { type: 'string' },
          replacement: { type: 'string' },
          kind: { type: 'string', enum: ['spelling', 'grammar', 'punctuation', 'style'] },
          explanation: { type: 'string' },
        },
        required: ['before', 'original', 'replacement', 'kind', 'explanation'],
        additionalProperties: false,
      },
    },
  },
  required: ['corrections'],
  additionalProperties: false,
};


/** The user turn. Same wording wherever the request is built. */
function userPrompt(text) {
  return `Proofread the text between the markers.\n\n<text>\n${text}\n</text>`;
}

/**
 * Pull the corrections out of whatever the model said.
 *
 * Small models ignore "reply with JSON" more often than large ones: they wrap
 * it in a code fence, or say "Sure! Here you go:" first. Rather than fail the
 * whole check on that, find the JSON and move on.
 */
function parseCorrections(raw) {
  if (!raw || typeof raw !== 'string') return null;
  const tries = [raw];
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fenced) tries.push(fenced[1]);
  const braced = raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1);
  if (braced.length > 1) tries.push(braced);
  for (const candidate of tries) {
    try {
      const parsed = JSON.parse(candidate.trim());
      if (parsed && Array.isArray(parsed.corrections)) return parsed.corrections;
    } catch (_) { /* try the next shape */ }
  }
  return null;
}

// How many "leave this alone" items to send. Long enough to cover the words a
// person actually keeps rejecting, short enough that the note stays a footnote
// rather than becoming most of the prompt.
const MAX_LEAVE_ALONE = 60;

/**
 * The note that tells the model what this writer has already said no to.
 *
 * Caret filters these out locally anyway, so the model's suggestion would be
 * thrown away either way. The point is that it stops spending one of its few
 * suggestions re-proposing something that has been rejected before, and stops
 * the writer being nagged about the way they write.
 *
 * Everything in here was chosen deliberately by the writer - a word they added
 * to their dictionary, or a correction they pressed Ignore on. None of it is
 * guessed from their writing.
 *
 * @param {string[]} items  words and phrases to leave alone
 * @returns {string} '' when there is nothing to say
 */
function leaveAloneNote(items) {
  const clean = [];
  const seen = new Set();
  for (const item of items || []) {
    const word = String(item || '').trim();
    // One word or a short phrase. Anything longer is not a word they rejected,
    // it is a sentence, and it does not belong in the prompt.
    if (!word || word.length > 40 || seen.has(word.toLowerCase())) continue;
    seen.add(word.toLowerCase());
    clean.push(word);
    if (clean.length >= MAX_LEAVE_ALONE) break;
  }
  if (!clean.length) return '';

  return [
    '',
    'This writer has already told the checker to leave the following words and',
    'phrases alone - either by adding them to their dictionary or by dismissing',
    'a correction to them. This is how they write on purpose.',
    '',
    'NEVER propose a change to any of them, in any sentence, for any reason,',
    'including spelling, capitalization and punctuation inside them:',
    clean.map((w) => `  ${w}`).join('\n'),
  ].join('\n');
}

// The Caret Worker: a free AI proofreading pass for a handful of people.
//
// Why it exists. The extension can already call Google, OpenAI or Anthropic
// directly, but each person has to go and get their own API key first. This
// removes that step for a small, known group: one Cloudflare account runs the
// model, and each person gets a short Caret key to paste instead.
//
// What it is not. It is not a service. The Workers AI free plan allows 10,000
// neurons a day across the whole account, and when they are gone every request
// fails until 00:00 UTC. That is roughly 900-1,200 checks a day shared between
// everyone, so the per-key daily cap below matters: without it one person
// leaving "after every pause" switched on takes the day's allowance by lunch.
//
// What it never does: store the text it is sent, or log it. The only things
// written down are counters.


// Models get retired, and when one does every request fails with a 5028 until
// somebody notices and edits a setting. So this is a list, tried in order, and
// a retired or unknown model costs one wasted call rather than a day of
// outage. Set MODEL in the dashboard to force a particular one to the front.
//
// Ordered best-first among models that are on the free plan. Verify with
// test/quality.mjs before reordering: a bigger model is not automatically
// better at leaving correct writing alone, which is the thing that matters.
const MODELS = [
  '@cf/meta/llama-3.3-70b-instruct-fp8-fast',
  '@cf/google/gemma-4-26b-a4b-it',
  '@cf/zai-org/glm-4.7-flash',
  '@cf/meta/llama-3.1-8b-instruct-fp8',
  '@cf/meta/llama-3.2-3b-instruct',
];

/** A model that is gone, renamed or not on this plan. Try the next one. */
const DEAD_MODEL = /5028|deprecat|not found|no such model|unknown model|does not exist|invalid model|7000|7001/i;

/** The account is out of allowance. Trying another model will not help. */
const OUT_OF_ALLOWANCE = /neuron|quota|exceeded|capacity|3040/i;

// Matches the extension's own ceiling, so a long field is cut the same way.
const MAX_CHARS = 6000;

// Per key, per UTC day. The account-wide allowance is the real limit; this one
// is so that one person cannot spend all of it.
const DEFAULT_PER_KEY_DAILY = 120;

const CORS = {
  'access-control-allow-origin': '*',
  'access-control-allow-methods': 'POST, OPTIONS',
  'access-control-allow-headers': 'content-type, x-caret-key',
  'access-control-max-age': '86400',
};

const json = (body, status = 200) => new Response(JSON.stringify(body), {
  status,
  headers: { 'content-type': 'application/json', ...CORS },
});

const today = () => new Date().toISOString().slice(0, 10);

/**
 * Look the key up and count this call against it.
 * @returns {Promise<{ok: true, name: string, left: number} | {ok: false, status: number, error: string}>}
 */
async function spendKey(env, key) {
  if (!key || !/^caret_[A-Za-z0-9_-]{8,64}$/.test(key)) {
    return { ok: false, status: 401, error: 'That is not a Caret key.' };
  }

  const record = await env.KEYS.get(`key:${key}`, { type: 'json' });
  if (!record) return { ok: false, status: 401, error: 'This Caret key is not recognised.' };
  if (record.revoked) return { ok: false, status: 403, error: 'This Caret key has been turned off.' };

  const limit = Number(record.daily) > 0 ? Number(record.daily)
    : Number(env.PER_KEY_DAILY) || DEFAULT_PER_KEY_DAILY;
  const counter = `use:${key}:${today()}`;
  const used = Number(await env.KEYS.get(counter)) || 0;
  if (used >= limit) {
    return {
      ok: false,
      status: 429,
      error: `That is ${limit} checks today on this key. It resets at midnight UTC.`,
    };
  }

  // Two checks landing together can both read the same number; losing one off
  // the count matters far less than making every request wait on a lock.
  await env.KEYS.put(counter, String(used + 1), { expirationTtl: 60 * 60 * 36 });
  return { ok: true, name: record.name || 'someone', left: limit - used - 1 };
}

export default {
  async fetch(request, env) {
    if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers: CORS });

    const url = new URL(request.url);

    // A liveness check that says nothing about any key.
    if (request.method === 'GET' && url.pathname === '/health') {
      return json({
        ok: true,
        model: env.MODEL || MODELS[0],
        fallbacks: (env.MODEL ? [env.MODEL, ...MODELS.filter((m) => m !== env.MODEL)] : MODELS).length,
      });
    }

    if (request.method !== 'POST' || url.pathname !== '/check') {
      return json({ error: 'POST /check' }, 404);
    }

    let body;
    try {
      body = await request.json();
    } catch (_) {
      return json({ error: 'Body must be JSON.' }, 400);
    }

    const text = typeof body.text === 'string' ? body.text.slice(0, MAX_CHARS) : '';
    if (!text.trim()) return json({ corrections: [] });

    // Words the writer has told their own copy of Caret to leave alone. Taken
    // as untrusted input: strings only, short ones, and a bounded number of
    // them, so a bad client cannot use this to write the prompt.
    const leaveAlone = Array.isArray(body.leaveAlone)
      ? body.leaveAlone.filter((w) => typeof w === 'string' && w.length <= 40).slice(0, 80)
      : [];

    const gate = await spendKey(env, request.headers.get('x-caret-key') || body.key);
    if (!gate.ok) return json({ error: gate.error }, gate.status);

    // Try the configured model first, then the rest of the list.
    const candidates = env.MODEL
      ? [env.MODEL, ...MODELS.filter((m) => m !== env.MODEL)]
      : MODELS;

    const ask = (model, withSchema) => env.AI.run(model, {
      messages: [
        { role: 'system', content: SYSTEM_PROMPT + leaveAloneNote(leaveAlone) },
        { role: 'user', content: userPrompt(text) },
      ],
      // Asked for, not relied on: Workers AI says it cannot guarantee the
      // schema is met, and fewer models support it than not. parseCorrections
      // picks up the pieces either way, so a model that rejects the parameter
      // outright is retried without it rather than written off.
      ...(withSchema ? { response_format: { type: 'json_schema', json_schema: SCHEMA } } : {}),
      max_tokens: 1200,
      temperature: 0,
    });

    let reply;
    let model;
    let lastError = '';
    for (const candidate of candidates) {
      for (const withSchema of [true, false]) {
        try {
          reply = await ask(candidate, withSchema);
          model = candidate;
          break;
        } catch (error) {
          lastError = String((error && error.message) || error);
          // No point trying anything else: the day is spent, not the model
          // broken. Say so plainly so the extension can go quiet rather than
          // show an error nobody can act on.
          if (OUT_OF_ALLOWANCE.test(lastError)) {
            return json({
              error: 'The shared daily allowance is used up. It resets at midnight UTC.',
              spent: true,
            }, 429);
          }
          // A retired model is worth skipping immediately; anything else gets
          // the no-schema retry first.
          if (DEAD_MODEL.test(lastError)) break;
        }
      }
      if (model) break;
    }

    if (!model) return json({ error: `No model would answer. Last said: ${lastError}` }, 502);

    const raw = typeof reply === 'string' ? reply : (reply.response ?? reply.result ?? '');
    const corrections = parseCorrections(typeof raw === 'string' ? raw : JSON.stringify(raw));
    if (!corrections) return json({ corrections: [], unparsed: true });

    // Hand back the same shape every other provider produces, so the extension
    // runs it through exactly the same toIssues() it always has.
    return json({ corrections, model, left: gate.left });
  },
};
